configuration.bicep:
targetScope = 'subscription'

@description('Resource ID of the built-in Allowed locations definition')
param allowedLocationsDefinitionId string

resource allowedLocations 'Microsoft.Authorization/policyAssignments@2022-06-01' = {
  name: 'allowed-locations'
  properties: {
    policyDefinitionId: allowedLocationsDefinitionId
    enforcementMode: 'Default'
    notScopes: [ '${subscription().id}/resourceGroups/rg-sandbox' ]
    parameters: {
      listOfAllowedLocations: { value: [ 'westeurope', 'northeurope' ] }
    }
  }
}
